// Wejście: tablica zadań z ClickUp
const inputItems = items.map(item => item.json);

// Zbuduj JEDEN obiekt ze wszystkimi zadaniami scalonymi razem
const aggregatedData = {};
let tasksOutput = "";

inputItems.forEach((task, index) => {
  const num = index + 1; // numeracja od 1

  // Dodaj każde pole z numerowanym sufiksem
  aggregatedData[`taskId_${num}`] = task.taskId || "";
  aggregatedData[`name_${num}`] = task.name || "";
  aggregatedData[`description_${num}`] = task.description || "";

  aggregatedData[`createdDate_${num}`] = task.createdDate || "";
  aggregatedData[`dueDate_${num}`] = task.dueDate || "";
  aggregatedData[`updatedDate_${num}`] = task.updatedDate || "";

  aggregatedData[`status_${num}`] = task.status || "";
  aggregatedData[`priority_${num}`] = task.priority || "";

  aggregatedData[`customFields_${num}`] = task.customFields ? JSON.stringify(task.customFields) : "";
  aggregatedData[`tags_${num}`] = task.tags || "";

  aggregatedData[`listId_${num}`] = task.listId || "";
  aggregatedData[`folderId_${num}`] = task.folderId || "";
  aggregatedData[`spaceId_${num}`] = task.spaceId || "";
  aggregatedData[`taskUrl_${num}`] = task.taskUrl || "";

  // Zbuduj scalony tasksOutput dla tej iteracji
  const separator = index < inputItems.length - 1 ? "\n---\n" : "";
  tasksOutput += `[Zadanie ${num}] ${task.name || "(brak nazwy)"}\n${task.description || "(brak opisu)"}${separator}`;
});

// Dodaj metadane o łącznej liczbie zadań
aggregatedData._totalTasks = inputItems.length;

// Dodaj scalony tasksOutput
aggregatedData.tasksOutput = tasksOutput.trim();

// Zwróć jako POJEDYNCZY element n8n
return [{ json: aggregatedData }];
